import React from 'react';
import Blobs from '../components/Blobs';
import Orb3D from '../components/Orb3D';
import { useMoods, useThoughts } from '../hooks/useStorage';

const TRAP_ICONS = { 'Katastrofiering':'🌪️','Tankeläsning':'🔮','Svartvitt tänkande':'⬛','Övergeneralisering':'🔁','Känslomässigt resonerande':'💭','Personalisering':'🎯','Filtrerande':'🔍','Bör-tänkande':'📋' };
const MOOD_COLORS = { 1:'#e05050',2:'#e07840',3:'#c0a040',4:'#50b070',5:'#5090d0' };

export default function History({ setPage }) {
  const { moods, streak, avgMood } = useMoods();
  const { thoughts, trapCounts }   = useThoughts();
  const isEmpty = moods.length === 0 && thoughts.length === 0;
  const maxTrap = Math.max(...Object.values(trapCounts), 1);
  const avgEmoji = ['','😔','😟','😐','🙂','😄'];

  if (isEmpty) return (
    <div style={{ minHeight:'100vh', position:'relative', overflow:'hidden', display:'flex', alignItems:'center', justifyContent:'center' }}>
      <Blobs />
      <div style={{ position:'absolute', top:'-20%', left:'-20%', zIndex:0, opacity:0.5, pointerEvents:'none' }}>
        <Orb3D size={400} colors={['#303060','#101028','#5050a0']} speed={0.15} morphing={false} />
      </div>
      <div style={{ position:'relative', zIndex:1, textAlign:'center', padding:'0 32px' }}>
        <h2 style={{ fontSize:'clamp(28px,6vw,44px)', fontWeight:700, color:'#fff', marginBottom:14, letterSpacing:'-0.04em' }}>Ingen data än</h2>
        <p style={{ fontSize:14, color:'rgba(255,255,255,0.4)', marginBottom:36, fontWeight:300 }}>Börja med en tankeanalys eller daglig check-in.</p>
        <div style={{ display:'flex', gap:12, justifyContent:'center', flexWrap:'wrap' }}>
          <button onClick={()=>setPage('home')} style={{ padding:'12px 24px', borderRadius:100, background:'rgba(255,255,255,0.9)', color:'#13121a', fontSize:13, fontWeight:600 }}>Analysera en tanke</button>
          <button onClick={()=>setPage('checkin')} className="glass" style={{ padding:'12px 24px', borderRadius:100, color:'rgba(255,255,255,0.6)', fontSize:13 }}>Check-in</button>
        </div>
      </div>
    </div>
  );

  return (
    <div style={{ minHeight:'100vh', position:'relative', overflow:'hidden' }}>
      <Blobs />
      <div style={{ position:'absolute', top:'-18%', right:'-18%', zIndex:0, opacity:0.55, pointerEvents:'none', animation:'drift 16s ease-in-out infinite' }}>
        <Orb3D size={400} colors={['#404080','#181830','#6060b0']} speed={0.12} />
      </div>

      <div style={{ position:'relative', zIndex:1, padding:'88px 32px 64px', maxWidth:520, margin:'0 auto', animation:'fadeUp .7s cubic-bezier(0.16,1,0.3,1) both' }}>

        {/* Big heading */}
        <h1 style={{ fontSize:'clamp(44px,9vw,68px)', fontWeight:700, letterSpacing:'-0.055em', lineHeight:0.88, color:'#fff', marginBottom:40 }}>
          DIN<br/><span style={{ color:'rgba(255,255,255,0.2)' }}>HISTORIK</span>
        </h1>

        {/* Stats */}
        <div style={{ display:'grid', gridTemplateColumns:'repeat(3,1fr)', gap:8, marginBottom:28 }}>
          {[
            { val:`🔥 ${streak}`, label:'Streak' },
            { val:thoughts.length, label:'Analyser' },
            { val:avgMood>0?`${avgEmoji[Math.round(avgMood)]} ${avgMood}`:'—', label:'Snitt' },
          ].map(({val,label})=>(
            <div key={label} className="glass" style={{ borderRadius:16, padding:'16px 12px', textAlign:'center' }}>
              <div style={{ fontSize:20, fontWeight:700, color:'#fff', marginBottom:4, lineHeight:1 }}>{val}</div>
              <div style={{ fontFamily:'DM Mono,monospace', fontSize:8, color:'rgba(255,255,255,0.28)', letterSpacing:'0.12em', textTransform:'uppercase' }}>{label}</div>
            </div>
          ))}
        </div>

        {/* Mood chart */}
        {moods.length > 0 && (
          <div className="glass" style={{ borderRadius:20, padding:'20px', marginBottom:10 }}>
            <p style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.16em', textTransform:'uppercase', color:'rgba(255,255,255,0.25)', marginBottom:16 }}>Humör</p>
            <div style={{ display:'flex', alignItems:'flex-end', gap:4, height:72 }}>
              {[...moods].reverse().map((m,i)=>(
                <div key={i} style={{ flex:1, display:'flex', flexDirection:'column', alignItems:'center', gap:3, height:'100%', justifyContent:'flex-end' }}>
                  <span style={{ fontSize:10 }}>{m.emoji}</span>
                  <div style={{ width:'100%', borderRadius:'3px 3px 0 0', background:MOOD_COLORS[m.score], height:`${(m.score/5)*100}%`, minHeight:4, boxShadow:`0 0 10px ${MOOD_COLORS[m.score]}66` }} />
                  <span style={{ fontFamily:'DM Mono,monospace', fontSize:7, color:'rgba(255,255,255,0.2)', whiteSpace:'nowrap' }}>
                    {new Date(m.date).toLocaleDateString('sv-SE',{day:'2-digit',month:'2-digit'})}
                  </span>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Trap freq */}
        {Object.keys(trapCounts).length > 0 && (
          <div className="glass" style={{ borderRadius:20, padding:'20px', marginBottom:10 }}>
            <p style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.16em', textTransform:'uppercase', color:'rgba(255,255,255,0.25)', marginBottom:16 }}>Vanligaste tankefällor</p>
            {Object.entries(trapCounts).sort((a,b)=>b[1]-a[1]).map(([label,count])=>(
              <div key={label} style={{ display:'flex', alignItems:'center', gap:10, marginBottom:10 }}>
                <span style={{ fontSize:12, width:16, flexShrink:0 }}>{TRAP_ICONS[label]||'💭'}</span>
                <span style={{ fontFamily:'DM Mono,monospace', fontSize:10, color:'rgba(255,255,255,0.45)', flex:1, overflow:'hidden', textOverflow:'ellipsis', whiteSpace:'nowrap' }}>{label}</span>
                <div style={{ width:64, height:2, background:'rgba(255,255,255,0.07)', borderRadius:1, flexShrink:0 }}>
                  <div style={{ height:'100%', borderRadius:1, background:'rgba(255,255,255,0.4)', width:`${(count/maxTrap)*100}%`, boxShadow:'0 0 6px rgba(255,255,255,0.2)' }} />
                </div>
                <span style={{ fontFamily:'DM Mono,monospace', fontSize:9, color:'rgba(255,255,255,0.25)', width:14, textAlign:'right' }}>{count}</span>
              </div>
            ))}
          </div>
        )}

        {/* Thought entries */}
        {thoughts.length > 0 && (
          <>
            <p style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.16em', textTransform:'uppercase', color:'rgba(255,255,255,0.25)', margin:'24px 0 10px' }}>Tidigare analyser</p>
            {thoughts.map(t=>(
              <div key={t.id} className="glass" style={{ borderRadius:16, padding:'16px 18px', marginBottom:8 }}>
                <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center', marginBottom:8 }}>
                  <span style={{ fontFamily:'DM Mono,monospace', fontSize:10, color:'rgba(255,255,255,0.45)' }}>{t.trap_icon||'💭'} {t.trap_label}</span>
                  <span style={{ fontFamily:'DM Mono,monospace', fontSize:9, color:'rgba(255,255,255,0.2)' }}>{new Date(t.date).toLocaleDateString('sv-SE',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'})}</span>
                </div>
                <p style={{ fontSize:12, color:'rgba(255,255,255,0.28)', fontStyle:'italic', marginBottom:10, lineHeight:1.6 }}>"{t.user_text?.slice(0,100)}{t.user_text?.length>100?'...':''}"</p>
                <p style={{ fontSize:13, color:'rgba(255,255,255,0.6)', lineHeight:1.65, fontWeight:300 }}>{t.reframe}</p>
              </div>
            ))}
          </>
        )}
      </div>
    </div>
  );
}
